def triage(log_text):
    counts = {'ERROR': 0, 'WARN': 0}
    msgs = {}
    for line in log_text.splitlines():
        parts = line.split(' ', 4)
        if len(parts) < 5:
            continue
        level = parts[2]
        if level in counts:
            counts[level] += 1
        if level == 'ERROR':
            msg = parts[4].split(': ', 1)[-1]
            msgs[msg] = msgs.get(msg, 0) + 1
    top = max(msgs, key=msgs.get) if msgs else None
    return {'ERROR': counts['ERROR'], 'WARN': counts['WARN'], 'top': top}

